"""Editorial revision: specific misconceptions replace weak distractors."""
import json
from pathlib import Path
P=Path(__file__).with_name('editorial.json')
d=json.loads(P.read_text())
def R(lid,n,*wrong):
 q=d['questions'][lid][n-1]
 indices=[i for i in range(len(q['options'])) if i not in q['correct']]
 for i,s in zip(indices,wrong):q['options'][i]=s.split('~',1)
